package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import java.time.Duration;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LeanMemory166Test {
 Context c;ActivityController<Activity> ctrl;Activity a;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("profile",0).edit().putString("id","123").commit();ctrl=Robolectric.buildActivity(Activity.class).setup();a=ctrl.get();}
 @After public void cleanup(){ctrl.pause().stop().destroy();ResidentChecks.resetForTest();}
 Library.Track track(String id)throws Exception{return LibraryUi163Test.song(id,"Song "+id);}
 String huge(int n){char[] chars=new char[n];Arrays.fill(chars,'x');return new String(chars);}
 JSONObject heavy()throws Exception{return new JSONObject().put("id","9").put("title","Title").put("duration",180000).put("full_duration",185000).put("policy","SNIP").put("downloadable",true).put("streamable",true).put("genre","Rock").put("permalink_url","https://soundcloud.com/example/track").put("artwork_url",JSONObject.NULL).put("description",huge(300000)).put("media",new JSONObject().put("transcodings",new JSONArray().put(new JSONObject().put("url","https://api-v2.soundcloud.com/transcoding")))).put("user",new JSONObject().put("username","Artist").put("avatar_url","https://i1.sndcdn.com/avatar-large.jpg").put("description",huge(300000)));}
 @Test public void apiTrackDoesNotRetainFullResponse()throws Exception{JSONObject raw=heavy();Library.Track t=ScApi.track(raw);assertNotSame(raw,t.remote);assertTrue(t.remote.toString().length()<1000);assertFalse(t.remote.has("media"));assertFalse(t.remote.has("user"));assertFalse(t.remote.has("description"));assertTrue(raw.has("description"));assertEquals("Artist",t.artist);assertEquals("Title",t.title);assertEquals("https://i1.sndcdn.com/avatar-large.jpg",t.artwork());}
 @Test public void compactMetadataPreservesQualityAndRights()throws Exception{Library.Track t=ScApi.track(heavy());assertEquals("9",t.id());assertEquals(185000,OfflineQuality.expected(t));assertTrue(t.preview());assertTrue(t.remote.optBoolean("downloadable"));assertTrue(t.remote.optBoolean("streamable"));assertEquals("Rock",t.remote.optString("genre"));assertEquals("https://soundcloud.com/example/track",t.link());}
 @Test public void jsonRestoresOnlySmallMetadata()throws Exception{JSONObject j=new JSONObject().put("uri","sc:9").put("title","T").put("remote",heavy());Library.Track t=Library.fromJson(j);assertFalse(t.remote.has("description"));assertFalse(t.remote.has("media"));assertFalse(t.artwork().isEmpty());}
 @Test public void oldLibraryLoadedCompactWithoutDeletingAnyTrack()throws Exception{JSONArray rows=new JSONArray();for(int i=0;i<10;i++)rows.put(new JSONObject().put("uri","sc:"+i).put("title","T"+i).put("remote",heavy()));c.getSharedPreferences("library",0).edit().putString("tracks",rows.toString()).commit();Library lib=new Library(c);assertEquals(10,lib.tracks.size());for(Library.Track t:lib.tracks)assertTrue(t.remote.toString().length()<1000);}
 @Test public void playlistCardsExcludeInlineTracksAndUserPayload()throws Exception{JSONObject raw=heavy().put("track_count",1234).put("tracks",new JSONArray().put(heavy()));JSONObject card=ScApi.playlistSummary(raw);assertFalse(card.has("tracks"));assertFalse(card.has("media"));assertFalse(card.has("description"));assertEquals(1234,card.optInt("track_count"));assertEquals("Artist",card.optJSONObject("user").optString("username"));assertFalse(card.optJSONObject("user").has("description"));}
 @Test public void snapshotsLiveOnDiskAndListIsLight()throws Exception{PlaylistCache cache=new PlaylistCache(c);ArrayList<Library.Track> tracks=new ArrayList<>();for(int i=0;i<500;i++)tracks.add(track(""+i));cache.put("big","Big","own",tracks,true,"123");assertTrue(c.getSharedPreferences("playlist_snapshots",0).getAll().isEmpty());assertTrue(c.getDatabasePath("playlist_snapshots.db").isFile());JSONObject card=cache.list("own").get(0);assertFalse(card.has("tracks"));assertTrue(card.optBoolean("requested"));assertEquals(500,cache.tracks("big").size());assertEquals("2 / 500 на устройстве",cache.progress("big",new HashSet<>(Arrays.asList("1","2"))));}
 @Test public void migratesLegacySnapshotsAndOtherAccounts()throws Exception{SharedPreferences old=c.getSharedPreferences("playlist_snapshots",0);JSONObject j=new JSONObject().put("id","p").put("title","Old").put("kind","own").put("cached",true).put("requested",true).put("track_count",2).put("tracks",new JSONArray().put(Library.json(track("1"))).put(Library.json(track("2"))));old.edit().putString("123:p",j.toString()).putString("999:p",new JSONObject(j.toString()).put("title","Other").toString()).commit();PlaylistCache cache=new PlaylistCache(c);assertTrue(old.getAll().isEmpty());assertEquals("Old",cache.get("p").optString("title"));assertTrue(cache.get("p").optBoolean("requested"));assertEquals(2,cache.tracks("p").size());c.getSharedPreferences("profile",0).edit().putString("id","999").commit();assertEquals("Other",cache.get("p").optString("title"));}
 @Test public void requestedFlagSurvivesRefreshAndEmptyListKnown()throws Exception{PlaylistCache cache=new PlaylistCache(c);cache.put("p","P","own",Arrays.asList(track("1")),true,"123");cache.put("p","P","own",Collections.emptyList(),false,"123");assertTrue(cache.contains("p"));assertTrue(cache.get("p").optBoolean("requested"));assertEquals("0 / 0 на устройстве",cache.progress("p",Collections.emptySet()));assertTrue(cache.tracks("p").isEmpty());}
 @Test public void legacyDoesNotOverwriteNewerDiskSnapshot()throws Exception{PlaylistCache cache=new PlaylistCache(c);cache.put("p","New","own",Arrays.asList(track("1")),false,"123");c.getSharedPreferences("playlist_snapshots",0).edit().putString("123:p",new JSONObject().put("id","p").put("title","Old").put("tracks",new JSONArray()).toString()).commit();assertEquals("New",new PlaylistCache(c).get("p").optString("title"));assertTrue(c.getSharedPreferences("playlist_snapshots",0).getAll().isEmpty());}
 @Test public void veryLargeSnapshotReadInCursorSafeChunks()throws Exception{PlaylistCache cache=new PlaylistCache(c);Library.Track t=track("1");t.reason=huge(3*1024*1024);cache.put("huge","Huge","own",Arrays.asList(t),false,"123");assertEquals(3*1024*1024,cache.tracks("huge").get(0).reason.length());assertFalse(cache.list("own").get(0).has("tracks"));assertEquals("1 / 1 на устройстве",cache.progress("huge",Collections.singleton("1")));}
 @Test public void diskSnapshotsRemainAccountIsolatedAndClearable()throws Exception{PlaylistCache cache=new PlaylistCache(c);cache.put("p","Mine","own",Arrays.asList(track("1")),false,"123");c.getSharedPreferences("profile",0).edit().putString("id","999").commit();assertNull(cache.get("p"));assertTrue(cache.list("own").isEmpty());try{cache.put("p","Wrong","own",Collections.emptyList(),false,"123");fail();}catch(java.io.IOException expected){}c.getSharedPreferences("profile",0).edit().putString("id","123").commit();assertTrue(cache.contains("p"));cache.clearAll();assertFalse(cache.contains("p"));}
 @Test public void playbackServiceHasNoRetainedFullLibrary()throws Exception{for(Field f:PlaybackService.class.getDeclaredFields())assertNotEquals(Library.class,f.getType());assertEquals(Library.Track.class,PlaybackService.class.getDeclaredField("activeTrack").getType());assertEquals(6*1024*1024,PlaybackMemory.TARGET_BYTES);assertEquals(30000,PlaybackMemory.MAX_MS);}
 @Test public void boundedImageCacheReducedWithoutSingleWorkerBottleneck(){assertEquals(2*1024*1024,ArtworkLoader.CACHE_BYTES);assertEquals(12,ArtworkLoader.MAX_PENDING);assertEquals(2,ArtworkLoader.WORKERS);}
 void size(View v){v.measure(View.MeasureSpec.makeMeasureSpec(400,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY));v.layout(0,0,400,600);}
 void send(View v,int action,float x,float y){MotionEvent e=MotionEvent.obtain(0,SystemClock.uptimeMillis(),action,x,y,0);v.dispatchTouchEvent(e);e.recycle();}
 HoldListView nested(AtomicInteger held,AtomicInteger clicks,AtomicInteger refreshed){HoldListView list=new HoldListView(a);list.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_list_item_1,new String[]{"first","second"}));list.setOnItemClickListener((p,v,pos,id)->clicks.incrementAndGet());list.setOnItemLongClickListener((p,v,pos,id)->{held.incrementAndGet();new AlertDialog.Builder(a).setTitle("Held menu").setItems(new String[]{"Offline"},null).show();return true;});PullRefreshLayout root=new PullRefreshLayout(a,()->true,refreshed::incrementAndGet);root.addView(list,0,new FrameLayout.LayoutParams(-1,-1));a.setContentView(root);size(root);return list;}
 @Test public void realDialogAppearsUnderPullParentBeforeRelease(){AtomicInteger held=new AtomicInteger(),clicks=new AtomicInteger();HoldListView list=nested(held,clicks,new AtomicInteger());View root=(View)list.getParent();send(root,0,25,25);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(351));AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(dialog);assertTrue(dialog.isShowing());assertEquals(1,held.get());assertEquals(0,clicks.get());send(root,1,25,25);assertEquals(1,held.get());assertEquals(0,clicks.get());dialog.dismiss();}
 @Test public void noNativeLongClickFallbackAfterRelease(){AtomicInteger held=new AtomicInteger(),clicks=new AtomicInteger();HoldListView list=nested(held,clicks,new AtomicInteger());assertFalse(list.isLongClickable());assertNull(list.getOnItemLongClickListener());View root=(View)list.getParent();send(root,0,25,25);send(root,1,25,25);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));assertEquals(0,held.get());assertEquals(1,clicks.get());}
 @Test public void dataReplacementCancelsOldHold(){AtomicInteger held=new AtomicInteger();HoldListView list=nested(held,new AtomicInteger(),new AtomicInteger());send((View)list.getParent(),0,25,25);((BaseAdapter)list.getAdapter()).notifyDataSetChanged();Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));assertEquals(0,held.get());}
 @Test public void verticalRefreshCancelsHoldAndDoesNotOpenOnUp(){AtomicInteger held=new AtomicInteger(),refresh=new AtomicInteger();HoldListView list=nested(held,new AtomicInteger(),refresh);View root=(View)list.getParent();send(root,0,25,25);send(root,2,25,200);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofMillis(600));send(root,1,25,200);assertEquals(0,held.get());assertEquals(1,refresh.get());}
}
